tool_calls.arguments:
{"sql":"SELECT pt.TrackId, t.Name AS TrackName, COUNT(DISTINCT pt.PlaylistId) AS PlaylistCount
FROM PlaylistTrack pt
JOIN Track t ON pt.TrackId = t.TrackId
GROUP BY pt.TrackId
HAVING PlaylistCount = (
  SELECT MAX(c) FROM (
    SELECT COUNT(DISTINCT PlaylistId) AS c FROM PlaylistTrack GROUP BY TrackId
  )
)
ORDER BY TrackName;"}

